(()=>{const A='#ff86c2',INK='#c9b9c9',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`body{background:radial-gradient(ellipse at 50% 0,#25284d 0,#0d1023 45%,#05060d 100%)}body:before{content:'';position:fixed;inset:0;pointer-events:none;z-index:-2;background:radial-gradient(circle at 18% 28%,#7e8bd518,transparent 28%),radial-gradient(circle at 82% 70%,#ff86c20c,transparent 32%)}.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fxbar i{display:block;height:100%;width:0;background:${A};box-shadow:0 0 15px ${A}}.fx-orb{position:fixed;border-radius:50%;pointer-events:none;filter:blur(100px);opacity:.13;z-index:-1}.fx-orb.a{width:450px;height:450px;left:-180px;top:5%;background:#5365a2;animation:drift 18s ease-in-out infinite}.fx-orb.b{width:400px;height:400px;right:-170px;bottom:5%;background:#d95b9d;animation:drift 22s ease-in-out infinite reverse}.confetti-ink{position:fixed;pointer-events:none;z-index:2;width:2px;height:14px;border-radius:100%;background:linear-gradient(180deg,transparent,${INK});opacity:0;filter:blur(.2px);animation:inkFall 9s linear infinite}.ink-dash{position:fixed;pointer-events:none;z-index:2;width:18px;height:5px;border-radius:70% 20% 60% 30%;background:${INK};opacity:0;filter:blur(.25px);animation:inkDrift 11s ease-in-out infinite}.fx-heart{position:fixed;pointer-events:none;z-index:2;color:${A};opacity:0;filter:drop-shadow(0 0 8px #ff86c244);animation:heart 12s ease-out infinite}.fxr{opacity:0;transform:translateY(38px) scale(.985);transition:1s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}.writing:after{content:'|';animation:cursor .8s steps(1) infinite;color:${A}}.photo-slot.focused{transform:scale(1.025) rotate(-1deg);box-shadow:0 30px 90px #ff4f9d22}.answer-pop{animation:answer .7s ease}@keyframes drift{50%{transform:translate(85px,-50px)}}@keyframes inkFall{0%{transform:translate3d(0,-8vh,0) rotate(8deg);opacity:0}12%{opacity:.22}60%{opacity:.12}100%{transform:translate3d(28px,108vh,0) rotate(80deg);opacity:0}}@keyframes inkDrift{0%,100%{transform:translate3d(0,20px,0) rotate(-22deg) scale(.65);opacity:0}22%{opacity:.18}55%{transform:translate3d(45px,-45px,0) rotate(18deg) scale(1.1);opacity:.1}80%{opacity:0}}@keyframes heart{0%{transform:translate3d(0,20vh,0) rotate(-10deg) scale(.65);opacity:0}18%{opacity:.4}100%{transform:translate3d(35px,-105vh,0) rotate(28deg) scale(1);opacity:0}}@keyframes cursor{50%{opacity:0}}@keyframes answer{50%{transform:scale(1.06)}}@media(prefers-reduced-motion:reduce){.confetti-ink,.ink-dash,.fx-heart{display:none}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);['a','b'].forEach(c=>{const o=document.createElement('div');o.className='fx-orb '+c;b.appendChild(o)});if(!reduce){for(let i=0;i<20;i++){const p=document.createElement('i');p.className='confetti-ink';p.style.left=Math.random()*100+'%';p.style.animationDelay=-Math.random()*9+'s';p.style.animationDuration=7+Math.random()*6+'s';p.style.height=8+Math.random()*12+'px';b.appendChild(p)}for(let i=0;i<10;i++){const d=document.createElement('i');d.className='ink-dash';d.style.left=Math.random()*100+'%';d.style.top=10+Math.random()*85+'%';d.style.animationDelay=-Math.random()*11+'s';d.style.animationDuration=9+Math.random()*7+'s';b.appendChild(d)}for(let i=0;i<8;i++){const h=document.createElement('span');h.className='fx-heart';h.textContent=i%3===0?'♡':'·';h.style.left=8+Math.random()*84+'%';h.style.fontSize=12+Math.random()*12+'px';h.style.animationDelay=-Math.random()*12+'s';h.style.animationDuration=10+Math.random()*7+'s';b.appendChild(h)}}document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();